    { const char * tb_v714 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v714; }
    { const char * tb_v715 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v715; }
    { const char * tb_v716 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v716; }
    { const char * tb_v717 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v717; }
    { const char * tb_v718 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v718; }
    { const char * tb_v719 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v719; }
    { const char * tb_v720 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v720; }
    { const char * tb_v721 = "        \".set tb_v, 0\\n.rept 49\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v721; }
    { const char * tb_v722 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v722; }
    { const char * tb_v723 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v723; }
    { const char * tb_v724 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v724; }
    { const char * tb_v725 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v725; }
    { const char * tb_v726 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v726; }
    { const char * tb_v727 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v727; }
    { const char * tb_v728 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v728; }
    { const char * tb_v729 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v729; }
    { const char * tb_v730 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v730; }
    { const char * tb_v731 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v731; }
    { const char * tb_v732 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v732; }
