    { const char * tb_v736 = "// --- задачи: у каждой свой стек и свои «переменные потока» (temp, кэш длины) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v736; }
    { const char * tb_v737 = "#define TB_TLS_MAX 512\n"; *(const char * *)tb_grow(v_lines) = tb_v737; }
