    { const char * tb_v739 = "#define TB_TSTACK 65536\n"; *(const char * *)tb_grow(v_lines) = tb_v739; }
    { const char * tb_v740 = "typedef struct { pthread_t th; volatile int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v740; }
    { const char * tb_v741 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v741; }
