    { const char * tb_v754 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v754; }
    { const char * tb_v755 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v755; }
    { const char * tb_v756 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v756; }
    { const char * tb_v757 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v757; }
    { const char * tb_v758 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v758; }
    { const char * tb_v759 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v759; }
