    { const char * tb_v761 = "    if (v >= 40) tb_pic_mask &= (uint16_t)~(1u << 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v761; }
    { const char * tb_v762 = "    tb_pic_apply();\n"; *(const char * *)tb_grow(v_lines) = tb_v762; }
    { const char * tb_v763 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v763; }
    { const char * tb_v764 = "TB_API void tb_irq_on(void) { __asm__ volatile(\"sti\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v764; }
    { const char * tb_v765 = "TB_API void tb_irq_off(void) { __asm__ volatile(\"cli\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v765; }
    { const char * tb_v766 = "TB_API void tb_yield(void) { if (!tb_in_irq) __asm__ volatile(\"int $48\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v766; }
    { const char * tb_v767 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v767; }
    { const char * tb_v768 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v768; }
    { const char * tb_v769 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v769; }
    { const char * tb_v770 = "    if (tb_nlive <= 1 && !tb_slots[tb_cur].done) return frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v770; }
    { const char * tb_v771 = "    int n = tb_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v771; }
    { const char * tb_v772 = "    for (int k = 1; k <= TB_NTASK; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v772; }
    { const char * tb_v773 = "        int j = (tb_cur + k) % TB_NTASK;\n"; *(const char * *)tb_grow(v_lines) = tb_v773; }
    { const char * tb_v774 = "        if (tb_slots[j].used && !tb_slots[j].done) { n = j; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v774; }
    { const char * tb_v775 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v775; }
    { const char * tb_v776 = "    tb_kslot *c = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v776; }
    { const char * tb_v777 = "    if (n == tb_cur) return frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v777; }
    { const char * tb_v778 = "    c->frame = frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v778; }
    { const char * tb_v779 = "    memcpy(c->tls, tb_tls_start, tb_tls_size());\n"; *(const char * *)tb_grow(v_lines) = tb_v779; }
    { const char * tb_v780 = "    if (c->done) { c->used = 0; tb_nlive--; }\n"; *(const char * *)tb_grow(v_lines) = tb_v780; }
    { const char * tb_v781 = "    tb_cur = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v781; }
    { const char * tb_v782 = "    memcpy(tb_tls_start, tb_slots[n].tls, tb_tls_size());\n"; *(const char * *)tb_grow(v_lines) = tb_v782; }
    { const char * tb_v783 = "    tb_slice = 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v783; }
    { const char * tb_v784 = "    return tb_slots[n].frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v784; }
    { const char * tb_v785 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v785; }
    { const char * tb_v786 = "TB_API void tb_task_entry(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v786; }
    { const char * tb_v787 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v787; }
    { const char * tb_v788 = "    s->run(s->arg);\n"; *(const char * *)tb_grow(v_lines) = tb_v788; }
    { const char * tb_v789 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v789; }
    { const char * tb_v790 = "    s->t->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v790; }
    { const char * tb_v791 = "    s->done = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v791; }
    { const char * tb_v792 = "    for (;;) __asm__ volatile(\"int $48\");\n"; *(const char * *)tb_grow(v_lines) = tb_v792; }
    { const char * tb_v793 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v793; }
    { const char * tb_v794 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v794; }
    { const char * tb_v795 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v795; }
    { const char * tb_v796 = "    int i = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v796; }
    { const char * tb_v797 = "    while (i < TB_NTASK && tb_slots[i].used) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v797; }
    { const char * tb_v798 = "    if (i == TB_NTASK) tb_panic(\"больше 31 задачи background сразу\", 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v798; }
    { const char * tb_v799 = "    tb_kslot *s = &tb_slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v799; }
    { const char * tb_v800 = "    s->used = 1; s->done = 0; s->run = run; s->arg = arg; s->t = t;\n"; *(const char * *)tb_grow(v_lines) = tb_v800; }
    { const char * tb_v801 = "    t->done = 0; t->th = i;\n"; *(const char * *)tb_grow(v_lines) = tb_v801; }
    { const char * tb_v802 = "    memcpy(s->tls, tb_tls_zero, TB_TLS_MAX);\n"; *(const char * *)tb_grow(v_lines) = tb_v802; }
    { const char * tb_v803 = "    // стек задачи выглядит так, будто её прервали прямо перед tb_task_entry\n"; *(const char * *)tb_grow(v_lines) = tb_v803; }
    { const char * tb_v804 = "    unsigned char *top = tb_tstacks[i] + TB_TSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v804; }
    { const char * tb_v805 = "    uint64_t *fr = (uint64_t *)(top - TB_FRAME);\n"; *(const char * *)tb_grow(v_lines) = tb_v805; }
    { const char * tb_v806 = "    memset(fr, 0, TB_FRAME);\n"; *(const char * *)tb_grow(v_lines) = tb_v806; }
    { const char * tb_v807 = "    memcpy(fr, tb_fpu_init, 512);\n"; *(const char * *)tb_grow(v_lines) = tb_v807; }
    { const char * tb_v808 = "    fr[TB_F_RIP] = (uint64_t)(uintptr_t)tb_task_entry;\n"; *(const char * *)tb_grow(v_lines) = tb_v808; }
    { const char * tb_v809 = "    fr[TB_F_RIP + 1] = 0x08;                       // cs\n"; *(const char * *)tb_grow(v_lines) = tb_v809; }
    { const char * tb_v810 = "    fr[TB_F_RIP + 2] = 0x202;                      // rflags: прерывания включены\n"; *(const char * *)tb_grow(v_lines) = tb_v810; }
    { const char * tb_v811 = "    fr[TB_F_RIP + 3] = (uint64_t)(uintptr_t)(top - 8);   // rsp: как после call\n"; *(const char * *)tb_grow(v_lines) = tb_v811; }
    { const char * tb_v812 = "    fr[TB_F_RIP + 4] = 0x10;                       // ss\n"; *(const char * *)tb_grow(v_lines) = tb_v812; }
    { const char * tb_v813 = "    s->frame = fr;\n"; *(const char * *)tb_grow(v_lines) = tb_v813; }
    { const char * tb_v814 = "    tb_nlive++;\n"; *(const char * *)tb_grow(v_lines) = tb_v814; }
    { const char * tb_v815 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v815; }
    { const char * tb_v816 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v816; }
    { const char * tb_v817 = "// a.crashed: задача упала (в ядре клетка падает одна; в обычной программе падает вся программа)\n"; *(const char * *)tb_grow(v_lines) = tb_v817; }
    { const char * tb_v818 = "TB_API _Bool tb_crashed(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v818; }
    { const char * tb_v819 = "    while (!t->done) tb_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v819; }
    { const char * tb_v820 = "    return t->done == 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v820; }
    { const char * tb_v821 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v821; }
    { const char * tb_v822 = "// a.wait: пока задача работает, отдаём ход другим\n"; *(const char * *)tb_grow(v_lines) = tb_v822; }
    { const char * tb_v823 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v823; }
    { const char * tb_v824 = "    if (tb_in_irq && !t->done) tb_panic(\"wait внутри прерывания нельзя\", 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v824; }
    { const char * tb_v825 = "    while (!t->done) tb_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v825; }
    { const char * tb_v826 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v826; }
    { const char * tb_v827 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v827; }
    { const char * tb_v828 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v828; }
