    { const char * tb_v1266 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1266; }
    { const char * tb_v1267 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v1267; }
    { const char * tb_v1268 = "typedef struct { char *data; long long len; long long cap; long long size; } tb_list;\n"; *(const char * *)tb_grow(v_lines) = tb_v1268; }
    { const char * tb_v1269 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
    { const char * tb_v1270 = "TB_COLD TB_API void tb_crash(int line, const char *msg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1270; }
    { const char * tb_v1271 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1271; }
    { const char * tb_v1272 = "    if (tb_cell_can_fall()) tb_cell_fall(msg, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v1272; }
