    { const char * tb_v1342 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1342; }
    { const char * tb_v1343 = "#define __builtin_ia32_pause_or_yield() __builtin_ia32_pause()\n"; *(const char * *)tb_grow(v_lines) = tb_v1343; }
