    { const char * tb_v1348 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1348; }
    { const char * tb_v1349 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v1349; }
    { const char * tb_v1350 = "TB_API void *tb_tramp_run(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1350; }
    { const char * tb_v1351 = "    tb_tramp t = *(tb_tramp *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1351; }
    { const char * tb_v1352 = "    free(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v1352; }
