    { const char * tb_v1374 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v1374; }
    { const char * tb_v1375 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1375; }
    { const char * tb_v1376 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v1376; }
