    { const char * tb_v1400 = "// начало программы на Windows: русский текст в консоли, цвета, слова запуска в UTF-8,\n"; *(const char * *)tb_grow(v_lines) = tb_v1400; }
    { const char * tb_v1401 = "// понятное сообщение при переполнении стека\n"; *(const char * *)tb_grow(v_lines) = tb_v1401; }
    { const char * tb_v1402 = "TB_API void tb_win_init(int *argc, char ***argv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1402; }
    { const char * tb_v1403 = "    SetConsoleOutputCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1403; }
    { const char * tb_v1404 = "    SetConsoleCP(CP_UTF8);\n"; *(const char * *)tb_grow(v_lines) = tb_v1404; }
    { const char * tb_v1405 = "    // \\n остаётся \\n (как на Linux и Mac): одинаковый вывод в файл и в трубу\n"; *(const char * *)tb_grow(v_lines) = tb_v1405; }
    { const char * tb_v1406 = "    _setmode(_fileno(stdout), _O_BINARY);\n"; *(const char * *)tb_grow(v_lines) = tb_v1406; }
