    { const char * tb_v1411 = "    if (GetConsoleMode(err, &mode) && SetConsoleMode(err, mode | 0x0004)) tb_win_vt = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1411; }
    { const char * tb_v1412 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1412; }
    { const char * tb_v1413 = "    wchar_t **wa = CommandLineToArgvW(GetCommandLineW(), &n);\n"; *(const char * *)tb_grow(v_lines) = tb_v1413; }
