    { const char * tb_v1415 = "        char **a = malloc(sizeof(char *) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v1415; }
    { const char * tb_v1416 = "        if (a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1416; }
    { const char * tb_v1417 = "            for (int i = 0; i < n; i++) a[i] = tb_narrow(wa[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v1417; }
    { const char * tb_v1418 = "            a[n] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1418; }
