    { const char * tb_v1438 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1438; }
    { const char * tb_v1439 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v1439; }
