    { const char * tb_v2115 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v2115; }
    { const char * tb_v2116 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2116; }
    { const char * tb_v2117 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2117; }
    { const char * tb_v2118 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2118; }
    { const char * tb_v2119 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2119; }
    { const char * tb_v2120 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2120; }
    { const char * tb_v2121 = "        long long old = l->cap / 8, cap = l->cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2121; }
    { const char * tb_v2122 = "        while (cap < need) cap *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2122; }
