    { const char * tb_v2126 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2126; }
    { const char * tb_v2127 = "    unsigned long long *w = (unsigned long long *)l->data;\n"; *(const char * *)tb_grow(v_lines) = tb_v2127; }
    { const char * tb_v2128 = "    long long i = l->len;\n"; *(const char * *)tb_grow(v_lines) = tb_v2128; }
    { const char * tb_v2129 = "    for (; i < need && (i & 63); i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2129; }
    { const char * tb_v2130 = "    if (need - i >= 64) { memset(w + (i >> 6), v ? 0xff : 0, ((need - i) >> 6) * 8); i += (need - i) & ~63LL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2130; }
    { const char * tb_v2131 = "    for (; i < need; i++) w[i >> 6] = v ? (w[i >> 6] | 1ULL << (i & 63)) : (w[i >> 6] & ~(1ULL << (i & 63)));\n"; *(const char * *)tb_grow(v_lines) = tb_v2131; }
