    { const char * tb_v2509 = "// ---------- http_get: страница из интернета через curl (есть на Mac и почти на любом Linux) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2509; }
    { const char * tb_v2510 = "TB_API const char *tb_http_get(const char *url) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2510; }
    { const char * tb_v2511 = "    if (strncmp(url, \"http://\", 7) != 0 && strncmp(url, \"https://\", 8) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2511; }
    { const char * tb_v2512 = "        tb_err = tb_cat(\"адрес должен начинаться с http:// или https://: \", url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2512; }
    { const char * tb_v2513 = "        return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v2513; }
    { const char * tb_v2514 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2514; }
    { const char * tb_v2515 = "    // адрес — в одинарных кавычках для shell: ' внутри адреса пишется как '\\''\n"; *(const char * *)tb_grow(v_lines) = tb_v2515; }
    { const char * tb_v2516 = "    size_t n = strlen(url);\n"; *(const char * *)tb_grow(v_lines) = tb_v2516; }
    { const char * tb_v2517 = "    char *cmd = malloc(n * 4 + 80);\n"; *(const char * *)tb_grow(v_lines) = tb_v2517; }
    { const char * tb_v2518 = "    if (!cmd) { tb_err = \"не хватило памяти\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2518; }
    { const char * tb_v2519 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v2519; }
    { const char * tb_v2520 = "    // curl.exe есть в Windows 10 и новее; адрес — в двойных кавычках для cmd.exe,\n"; *(const char * *)tb_grow(v_lines) = tb_v2520; }
    { const char * tb_v2521 = "    // (внутри кавычек & | < > ^ для cmd — простые знаки), а \" внутри адреса — как %22\n"; *(const char * *)tb_grow(v_lines) = tb_v2521; }
    { const char * tb_v2522 = "    size_t k = (size_t)sprintf(cmd, \"curl.exe -fsSL --max-time 30 \\\"\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2522; }
    { const char * tb_v2523 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2523; }
    { const char * tb_v2524 = "        unsigned char ch = (unsigned char)url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2524; }
    { const char * tb_v2525 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2525; }
    { const char * tb_v2526 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2526; }
    { const char * tb_v2527 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2527; }
    { const char * tb_v2528 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2528; }
    { const char * tb_v2529 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2529; }
    { const char * tb_v2530 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v2530; }
    { const char * tb_v2531 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2531; }
    { const char * tb_v2532 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2532; }
    { const char * tb_v2533 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2533; }
    { const char * tb_v2534 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v2534; }
    { const char * tb_v2535 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2535; }
    { const char * tb_v2536 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2536; }
    { const char * tb_v2537 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2537; }
