    { const char * tb_v2539 = "    free(cmd);\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "    if (p == 0) { tb_err = \"не могу запустить curl\"; return \"\"; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
    { const char * tb_v2541 = "    size_t cap = 4096, len = 0, got;\n"; *(const char * *)tb_grow(v_lines) = tb_v2541; }
    { const char * tb_v2542 = "    char *buf = tb_tmem(cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
