    { const char * tb_v2553 = "TB_API const char *tb_js_ws(const char *p) { while (*p == ' ' || *p == '\\n' || *p == '\\r' || *p == '\\t') p++; return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2553; }
    { const char * tb_v2554 = "// пропустить одно значение; адрес после него или 0, если JSON сломан\n"; *(const char * *)tb_grow(v_lines) = tb_v2554; }
    { const char * tb_v2555 = "TB_API const char *tb_js_skip(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2555; }
    { const char * tb_v2556 = "    p = tb_js_ws(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v2556; }
    { const char * tb_v2557 = "    if (*p == '\"') {\n"; *(const char * *)tb_grow(v_lines) = tb_v2557; }
    { const char * tb_v2558 = "        p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2558; }
