    { const char * tb_v2806 = "    void *p = tb_in_cur_temp(d->keys->data) ? tb_temp_alloc(bytes) : tb_gc_alloc_np(bytes);\n"; *(const char * *)tb_grow(v_lines) = tb_v2806; }
    { const char * tb_v2807 = "    if (!p) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2807; }
