    { const char * tb_v2809 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2809; }
    { const char * tb_v2810 = "TB_API void tb_dreindex(tb_dict *d, long long nslots) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2810; }
    { const char * tb_v2811 = "    d->mode = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2811; }
