    { const char * tb_v2979 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2979; }
    { const char * tb_v2980 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v2980; }
    { const char * tb_v2981 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v2981; }
    { const char * tb_v2982 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v2982; }
