    { const char * tb_v2986 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2986; }
    { const char * tb_v2987 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v2987; }
