    { const char * tb_v3296 = "    tb_memh *q = realloc(h, sizeof(tb_memh) + (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3296; }
    { const char * tb_v3297 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3297; }
    { const char * tb_v3298 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v3298; }
    { const char * tb_v3299 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3299; }
    { const char * tb_v3300 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3300; }
    { const char * tb_v3301 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3301; }
    { const char * tb_v3302 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3302; }
    { const char * tb_v3303 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
    { const char * tb_v3306 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
    { const char * tb_v3310 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3310; }
    { const char * tb_v3311 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
    { const char * tb_v3312 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3312; }
    { const char * tb_v3313 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3313; }
    { const char * tb_v3314 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3314; }
    { const char * tb_v3315 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3315; }
    { const char * tb_v3316 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3316; }
    { const char * tb_v3317 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3317; }
    { const char * tb_v3318 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3318; }
    { const char * tb_v3319 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3319; }
    { const char * tb_v3320 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3320; }
    { const char * tb_v3321 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
    { const char * tb_v3326 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3326; }
    { const char * tb_v3327 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3327; }
    { const char * tb_v3328 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3328; }
    { const char * tb_v3329 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3329; }
    { const char * tb_v3330 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3330; }
    { const char * tb_v3331 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
    { const char * tb_v3332 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3332; }
    { const char * tb_v3333 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3333; }
    { const char * tb_v3334 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3334; }
    { const char * tb_v3335 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3335; }
    { const char * tb_v3336 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3336; }
    { const char * tb_v3337 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3337; }
    { const char * tb_v3338 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3338; }
    { const char * tb_v3339 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3339; }
    { const char * tb_v3340 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3340; }
    { const char * tb_v3341 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3341; }
    { const char * tb_v3342 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3342; }
    { const char * tb_v3343 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3343; }
    { const char * tb_v3344 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
    { const char * tb_v3347 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3347; }
    { const char * tb_v3348 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3348; }
    { const char * tb_v3349 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
    { const char * tb_v3351 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3351; }
    { const char * tb_v3352 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3352; }
    { const char * tb_v3353 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3353; }
    { const char * tb_v3354 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3354; }
    { const char * tb_v3355 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3355; }
    { const char * tb_v3356 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3356; }
    { const char * tb_v3357 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v3357; }
    { const char * tb_v3358 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3358; }
    { const char * tb_v3359 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3359; }
    { const char * tb_v3360 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
    { const char * tb_v3361 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
    { const char * tb_v3370 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3370; }
    { const char * tb_v3371 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3371; }
    { const char * tb_v3372 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3372; }
    { const char * tb_v3373 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v3373; }
    { const char * tb_v3374 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3374; }
    { const char * tb_v3375 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3375; }
    { const char * tb_v3376 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3376; }
    { const char * tb_v3377 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3377; }
    { const char * tb_v3378 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3378; }
    { const char * tb_v3379 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
    { const char * tb_v3381 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v3381; }
    { const char * tb_v3382 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3382; }
    { const char * tb_v3383 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3383; }
    { const char * tb_v3384 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3384; }
    { const char * tb_v3385 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3385; }
    { const char * tb_v3386 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3386; }
    { const char * tb_v3387 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v3387; }
    { const char * tb_v3388 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3388; }
    { const char * tb_v3389 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3389; }
    { const char * tb_v3390 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3390; }
    { const char * tb_v3391 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3391; }
    { const char * tb_v3392 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3392; }
    { const char * tb_v3393 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3393; }
    { const char * tb_v3394 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3394; }
    { const char * tb_v3395 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3395; }
    { const char * tb_v3396 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3396; }
    { const char * tb_v3397 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3397; }
    { const char * tb_v3398 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v3398; }
    { const char * tb_v3399 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3399; }
    { const char * tb_v3400 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v3400; }
    { const char * tb_v3401 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3401; }
    { const char * tb_v3402 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3402; }
    { const char * tb_v3403 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3403; }
    { const char * tb_v3404 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3404; }
    { const char * tb_v3405 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3405; }
    { const char * tb_v3406 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3406; }
    { const char * tb_v3407 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3407; }
    { const char * tb_v3408 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3408; }
    { const char * tb_v3409 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v3409; }
    { const char * tb_v3410 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3410; }
    { const char * tb_v3411 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3411; }
    { const char * tb_v3412 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3412; }
    { const char * tb_v3413 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v3413; }
    { const char * tb_v3414 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3414; }
    { const char * tb_v3415 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3415; }
    { const char * tb_v3416 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3416; }
    { const char * tb_v3417 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3417; }
    { const char * tb_v3418 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3418; }
    { const char * tb_v3419 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v3419; }
    { const char * tb_v3420 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3420; }
    { const char * tb_v3421 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3421; }
    { const char * tb_v3422 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3422; }
    { const char * tb_v3423 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v3423; }
    { const char * tb_v3424 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3424; }
    { const char * tb_v3425 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3425; }
    { const char * tb_v3426 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3426; }
    { const char * tb_v3427 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3427; }
    { const char * tb_v3428 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3428; }
    { const char * tb_v3429 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3429; }
    { const char * tb_v3430 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3430; }
    { const char * tb_v3431 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3431; }
    { const char * tb_v3432 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3432; }
    { const char * tb_v3433 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3433; }
    { const char * tb_v3434 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v3434; }
    { const char * tb_v3435 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v3435; }
    { const char * tb_v3436 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v3436; }
    { const char * tb_v3437 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3437; }
    { const char * tb_v3438 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
