    { const char * tb_v3795 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
    { const char * tb_v3802 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3802; }
    { const char * tb_v3803 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3803; }
    { const char * tb_v3804 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v3804; }
    { const char * tb_v3805 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3805; }
    { const char * tb_v3806 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3806; }
    { const char * tb_v3807 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
    { const char * tb_v3811 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3811; }
    { const char * tb_v3812 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v3812; }
    { const char * tb_v3813 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v3813; }
    { const char * tb_v3814 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v3814; }
    { const char * tb_v3815 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v3815; }
    { const char * tb_v3816 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3816; }
    { const char * tb_v3817 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3817; }
    { const char * tb_v3818 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3818; }
    { const char * tb_v3819 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v3819; }
    { const char * tb_v3820 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3820; }
    { const char * tb_v3821 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3821; }
    { const char * tb_v3822 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3822; }
    { const char * tb_v3823 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3823; }
    { const char * tb_v3824 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
    { const char * tb_v3826 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3826; }
    { const char * tb_v3827 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3827; }
    { const char * tb_v3828 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3828; }
    { const char * tb_v3829 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
    { const char * tb_v3836 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3836; }
    { const char * tb_v3837 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3837; }
    { const char * tb_v3838 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
    { const char * tb_v3842 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v3842; }
    { const char * tb_v3843 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v3843; }
    { const char * tb_v3844 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v3844; }
    { const char * tb_v3845 = "// ---------- картинки PNG (load_image) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3845; }
    { const char * tb_v3846 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v3846; }
    { const char * tb_v3847 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v3847; }
    { const char * tb_v3848 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v3848; }
    { const char * tb_v3849 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v3849; }
    { const char * tb_v3850 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3850; }
    { const char * tb_v3851 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3851; }
    { const char * tb_v3852 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3852; }
    { const char * tb_v3853 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
    { const char * tb_v3855 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
    { const char * tb_v3857 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
    { const char * tb_v3862 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v3862; }
    { const char * tb_v3863 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3863; }
    { const char * tb_v3864 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v3864; }
    { const char * tb_v3865 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3865; }
    { const char * tb_v3866 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3866; }
    { const char * tb_v3867 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3867; }
    { const char * tb_v3868 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3868; }
    { const char * tb_v3869 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v3869; }
    { const char * tb_v3870 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v3870; }
    { const char * tb_v3871 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3871; }
    { const char * tb_v3872 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3872; }
