    { const char * tb_v4028 = "            if (ctype == 3) { unsigned i = s[0] < 256 ? s[0] : 0; R = pal[i][0]; G = pal[i][1]; B = pal[i][2]; A = pal[i][3]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4028; }
    { const char * tb_v4029 = "            else if (ctype == 0 || ctype == 4) { R = G = B = s[0]; A = ctype == 4 ? s[1] : (trns && raw[0] == key[0] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4029; }
    { const char * tb_v4030 = "            else { R = s[0]; G = s[1]; B = s[2]; A = ctype == 6 ? s[3] : (trns && raw[0] == key[0] && raw[1] == key[1] && raw[2] == key[2] ? 0 : 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4030; }
    { const char * tb_v4031 = "            px[(size_t)y * w + x] = (A << 24) | (R << 16) | (G << 8) | B;\n"; *(const char * *)tb_grow(v_lines) = tb_v4031; }
    { const char * tb_v4032 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4032; }
