    { const char * tb_v4036 = "    return px;\n"; *(const char * *)tb_grow(v_lines) = tb_v4036; }
    { const char * tb_v4037 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4037; }
    { const char * tb_v4038 = "// все картинки программы: точки подряд в одном большом массиве (его же видит видеокарта)\n"; *(const char * *)tb_grow(v_lines) = tb_v4038; }
    { const char * tb_v4039 = "typedef struct { int w, h; uint32_t off; } tb_image;\n"; *(const char * *)tb_grow(v_lines) = tb_v4039; }
    { const char * tb_v4040 = "TB_API tb_image *tb_imgs = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4040; }
    { const char * tb_v4041 = "TB_API int tb_nimg = 0, tb_img_dirty = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4041; }
    { const char * tb_v4042 = "TB_API uint32_t *tb_imgpx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4042; }
    { const char * tb_v4043 = "TB_API size_t tb_imgpx_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4043; }
    { const char * tb_v4044 = "TB_API long long tb_load_image(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4044; }
    { const char * tb_v4045 = "    FILE *f = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4045; }
    { const char * tb_v4046 = "    if (!f) { tb_err = \"нет такого файла картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4046; }
    { const char * tb_v4047 = "    fseek(f, 0, SEEK_END); long sz = ftell(f); fseek(f, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4047; }
    { const char * tb_v4048 = "    unsigned char *d = sz > 0 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4048; }
    { const char * tb_v4049 = "    if (!d || fread(d, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(d); tb_err = \"не могу прочитать файл картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4049; }
    { const char * tb_v4050 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v4050; }
    { const char * tb_v4051 = "    int w = 0, h = 0; const char *why = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4051; }
    { const char * tb_v4052 = "    uint32_t *px = tb_png(d, (size_t)sz, &w, &h, &why);\n"; *(const char * *)tb_grow(v_lines) = tb_v4052; }
    { const char * tb_v4053 = "    free(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v4053; }
