    { const char * tb_v4061 = "    if (!all || !list) { free(px); tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4061; }
    { const char * tb_v4062 = "    memcpy(tb_imgpx + tb_imgpx_n, px, (size_t)w * h * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4062; }
