    { const char * tb_v6871 = "    struct { uint32_t sType; const void *pNext; VkFlags flags; Display *dpy; Window window; } ci = { 1000004000, 0, 0, tb_dpy, tb_xw };\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
