    { const char * tb_v6873 = "        (VkResult (TBVK_CALL *)(VkInstance, const void *, const void *, VkSurfaceKHR *))tbvk_gipa(tb_vk.inst, \"vkCreateXlibSurfaceKHR\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6873; }
