    { const char * tb_v6876 = "// window_sharp в X11: масштаб из настройки Xft.dpi (её ставят GNOME и KDE), иначе 1\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "TB_API double tb_gfx_scale(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
    { const char * tb_v6879 = "    if (!tb_dpy) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6879; }
