    { const char * tb_v6882 = "    return dpi > 0 ? dpi / 96.0 : 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "TB_API int tb_gfx_open(const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "    if (!tb_dpy) tb_dpy = XOpenDisplay(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
    { const char * tb_v6886 = "    if (!tb_dpy) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6886; }
