    { const char * tb_v6894 = "    XSetWMProtocols(tb_dpy, tb_xw, &tb_wm_del, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "    XkbSetDetectableAutoRepeat(tb_dpy, True, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "    XMapWindow(tb_dpy, tb_xw);\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
    { const char * tb_v6897 = "    tb_ximg = XCreateImage(tb_dpy, DefaultVisual(tb_dpy, scr), 24, ZPixmap, 0, (char *)tb_px, tb_gw, tb_gh, 32, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6897; }
    { const char * tb_v6898 = "    if (tb_gpu_want()) tb_gpu_on = tb_vk_init(\"VK_KHR_xlib_surface\", tb_x_surface);\n"; *(const char * *)tb_grow(v_lines) = tb_v6898; }
    { const char * tb_v6899 = "    if (!tb_gpu_on) tb_gpu_say(\"процессор\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6899; }
    { const char * tb_v6900 = "    if (tb_cursor_want) tb_gfx_cursor(tb_cursor_want);\n"; *(const char * *)tb_grow(v_lines) = tb_v6900; }
    { const char * tb_v6901 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6901; }
    { const char * tb_v6902 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6902; }
    { const char * tb_v6903 = "// знак клавиши → буква Unicode (русская раскладка в X11 — свои старые номера 0x6c0..0x6ff)\n"; *(const char * *)tb_grow(v_lines) = tb_v6903; }
    { const char * tb_v6904 = "TB_API unsigned tb_x_uni(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6904; }
    { const char * tb_v6905 = "    static const unsigned short cyr[64] = { 0x44e, 0x430, 0x431, 0x446, 0x434, 0x435, 0x444, 0x433, 0x445, 0x438, 0x439, 0x43a, 0x43b, 0x43c, 0x43d, 0x43e, 0x43f, 0x44f, 0x440, 0x441, 0x442, 0x443, 0x436, 0x432, 0x44c, 0x44b, 0x437, 0x448, 0x44d, 0x449, 0x447, 0x44a, 0x42e, 0x410, 0x411, 0x426, 0x414, 0x415, 0x424, 0x413, 0x425, 0x418, 0x419, 0x41a, 0x41b, 0x41c, 0x41d, 0x41e, 0x41f, 0x42f, 0x420, 0x421, 0x422, 0x423, 0x416, 0x412, 0x42c, 0x42b, 0x417, 0x428, 0x42d, 0x429, 0x427, 0x42a };\n"; *(const char * *)tb_grow(v_lines) = tb_v6905; }
    { const char * tb_v6906 = "    if ((s >= 0x20 && s <= 0x7e) || (s >= 0xa0 && s <= 0xff)) return (unsigned)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6906; }
    { const char * tb_v6907 = "    if ((s & 0xff000000) == 0x01000000) return (unsigned)(s & 0xffffff);\n"; *(const char * *)tb_grow(v_lines) = tb_v6907; }
    { const char * tb_v6908 = "    if (s >= 0x6c0 && s <= 0x6ff) return cyr[s - 0x6c0];\n"; *(const char * *)tb_grow(v_lines) = tb_v6908; }
    { const char * tb_v6909 = "    if (s == 0x6a3) return 0x451;\n"; *(const char * *)tb_grow(v_lines) = tb_v6909; }
    { const char * tb_v6910 = "    if (s == 0x6b3) return 0x401;\n"; *(const char * *)tb_grow(v_lines) = tb_v6910; }
    { const char * tb_v6911 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6911; }
    { const char * tb_v6912 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6912; }
    { const char * tb_v6913 = "TB_API int tb_x_key(KeySym s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6913; }
    { const char * tb_v6914 = "    if (s >= XK_a && s <= XK_z) return 'A' + (int)(s - XK_a);\n"; *(const char * *)tb_grow(v_lines) = tb_v6914; }
    { const char * tb_v6915 = "    if (s >= XK_A && s <= XK_Z) return 'A' + (int)(s - XK_A);\n"; *(const char * *)tb_grow(v_lines) = tb_v6915; }
    { const char * tb_v6916 = "    if (s >= XK_0 && s <= XK_9) return '0' + (int)(s - XK_0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6916; }
    { const char * tb_v6917 = "    switch (s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6917; }
    { const char * tb_v6918 = "    case XK_Return: return TB_K_ENTER; case XK_Escape: return TB_K_ESC; case XK_space: return TB_K_SPACE;\n"; *(const char * *)tb_grow(v_lines) = tb_v6918; }
    { const char * tb_v6919 = "    case XK_BackSpace: return TB_K_BACK; case XK_Tab: return TB_K_TAB; case XK_Up: return TB_K_UP;\n"; *(const char * *)tb_grow(v_lines) = tb_v6919; }
    { const char * tb_v6920 = "    case XK_Down: return TB_K_DOWN; case XK_Left: return TB_K_LEFT; case XK_Right: return TB_K_RIGHT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6920; }
    { const char * tb_v6921 = "    case XK_Shift_L: case XK_Shift_R: return TB_K_SHIFT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6921; }
    { const char * tb_v6922 = "    case XK_Control_L: case XK_Control_R: return TB_K_CTRL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6922; }
    { const char * tb_v6923 = "    case XK_Alt_L: case XK_Alt_R: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6923; }
    { const char * tb_v6924 = "    case XK_Delete: return TB_K_DEL; case XK_Home: return TB_K_HOME; case XK_End: return TB_K_END;\n"; *(const char * *)tb_grow(v_lines) = tb_v6924; }
    { const char * tb_v6925 = "    case XK_Prior: return TB_K_PGUP; case XK_Next: return TB_K_PGDN;\n"; *(const char * *)tb_grow(v_lines) = tb_v6925; }
    { const char * tb_v6926 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6926; }
    { const char * tb_v6927 = "    if (s >= XK_F1 && s <= XK_F12) return TB_K_F1 + (int)(s - XK_F1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6927; }
    { const char * tb_v6928 = "    if (s > 0x20 && s < 0x7f) return (int)s;   // знаки [ ] . , / - = : у X11 номер знака — это его код\n"; *(const char * *)tb_grow(v_lines) = tb_v6928; }
    { const char * tb_v6929 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6929; }
    { const char * tb_v6930 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6930; }
    { const char * tb_v6931 = "// буфер обмена X11: текст держит сама программа-владелец и отдаёт его по просьбе (SelectionRequest)\n"; *(const char * *)tb_grow(v_lines) = tb_v6931; }
    { const char * tb_v6932 = "TB_API char *tb_x_clip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6932; }
    { const char * tb_v6933 = "TB_API void tb_x_clip_answer(XSelectionRequestEvent *r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6933; }
    { const char * tb_v6934 = "    Atom utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False), targets = XInternAtom(tb_dpy, \"TARGETS\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v6934; }
    { const char * tb_v6935 = "    XSelectionEvent ev;\n"; *(const char * *)tb_grow(v_lines) = tb_v6935; }
    { const char * tb_v6936 = "    memset(&ev, 0, sizeof ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v6936; }
    { const char * tb_v6937 = "    ev.type = SelectionNotify; ev.display = r->display; ev.requestor = r->requestor;\n"; *(const char * *)tb_grow(v_lines) = tb_v6937; }
    { const char * tb_v6938 = "    ev.selection = r->selection; ev.target = r->target; ev.time = r->time; ev.property = None;\n"; *(const char * *)tb_grow(v_lines) = tb_v6938; }
    { const char * tb_v6939 = "    Atom prop = r->property ? r->property : r->target;\n"; *(const char * *)tb_grow(v_lines) = tb_v6939; }
    { const char * tb_v6940 = "    if (r->target == targets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6940; }
    { const char * tb_v6941 = "        Atom list[3] = { targets, utf8, XA_STRING };\n"; *(const char * *)tb_grow(v_lines) = tb_v6941; }
    { const char * tb_v6942 = "        XChangeProperty(tb_dpy, r->requestor, prop, XA_ATOM, 32, PropModeReplace, (unsigned char *)list, 3);\n"; *(const char * *)tb_grow(v_lines) = tb_v6942; }
    { const char * tb_v6943 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v6943; }
    { const char * tb_v6944 = "    } else if ((r->target == utf8 || r->target == XA_STRING) && tb_x_clip) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6944; }
    { const char * tb_v6945 = "        XChangeProperty(tb_dpy, r->requestor, prop, r->target, 8, PropModeReplace, (unsigned char *)tb_x_clip, (int)strlen(tb_x_clip));\n"; *(const char * *)tb_grow(v_lines) = tb_v6945; }
    { const char * tb_v6946 = "        ev.property = prop;\n"; *(const char * *)tb_grow(v_lines) = tb_v6946; }
    { const char * tb_v6947 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6947; }
    { const char * tb_v6948 = "    XSendEvent(tb_dpy, r->requestor, False, 0, (XEvent *)&ev);\n"; *(const char * *)tb_grow(v_lines) = tb_v6948; }
    { const char * tb_v6949 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6949; }
    { const char * tb_v6950 = "TB_API void tb_gfx_clip_set(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6950; }
    { const char * tb_v6951 = "    free(tb_x_clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v6951; }
    { const char * tb_v6952 = "    tb_x_clip = strdup(s);\n"; *(const char * *)tb_grow(v_lines) = tb_v6952; }
    { const char * tb_v6953 = "    if (!tb_dpy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6953; }
    { const char * tb_v6954 = "    XSetSelectionOwner(tb_dpy, XInternAtom(tb_dpy, \"CLIPBOARD\", False), tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v6954; }
    { const char * tb_v6955 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v6955; }
    { const char * tb_v6956 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6956; }
    { const char * tb_v6957 = "TB_API char *tb_gfx_clip_get(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6957; }
    { const char * tb_v6958 = "    if (!tb_dpy) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6958; }
    { const char * tb_v6959 = "    Atom clip = XInternAtom(tb_dpy, \"CLIPBOARD\", False), utf8 = XInternAtom(tb_dpy, \"UTF8_STRING\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v6959; }
    { const char * tb_v6960 = "    Window owner = XGetSelectionOwner(tb_dpy, clip);\n"; *(const char * *)tb_grow(v_lines) = tb_v6960; }
    { const char * tb_v6961 = "    if (owner == tb_xw) return tb_x_clip ? strdup(tb_x_clip) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6961; }
    { const char * tb_v6962 = "    if (owner == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6962; }
    { const char * tb_v6963 = "    Atom prop = XInternAtom(tb_dpy, \"TACHBIT_CLIP\", False);\n"; *(const char * *)tb_grow(v_lines) = tb_v6963; }
    { const char * tb_v6964 = "    XConvertSelection(tb_dpy, clip, utf8, prop, tb_xw, CurrentTime);\n"; *(const char * *)tb_grow(v_lines) = tb_v6964; }
    { const char * tb_v6965 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v6965; }
    { const char * tb_v6966 = "    // ждём ответ владельца не дольше полсекунды; чужие события по дороге не теряем\n"; *(const char * *)tb_grow(v_lines) = tb_v6966; }
    { const char * tb_v6967 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v6967; }
    { const char * tb_v6968 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6968; }
    { const char * tb_v6969 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v6969; }
    { const char * tb_v6970 = "        if (XCheckTypedWindowEvent(tb_dpy, tb_xw, SelectionNotify, &e)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6970; }
    { const char * tb_v6971 = "            if (e.xselection.property == None) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6971; }
    { const char * tb_v6972 = "            Atom type; int fmt; unsigned long n = 0, rest = 0; unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6972; }
    { const char * tb_v6973 = "            XGetWindowProperty(tb_dpy, tb_xw, prop, 0, 1 << 24, True, AnyPropertyType, &type, &fmt, &n, &rest, &data);\n"; *(const char * *)tb_grow(v_lines) = tb_v6973; }
    { const char * tb_v6974 = "            char *out = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "            if (data && fmt == 8) { out = malloc(n + 1); if (out) { memcpy(out, data, n); out[n] = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "            if (data) XFree(data);\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "            return out;\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "        if (XCheckTypedEvent(tb_dpy, SelectionRequest, &e)) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
    { const char * tb_v6980 = "        struct timespec ts = { 0, 2000000 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6980; }
    { const char * tb_v6981 = "        nanosleep(&ts, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6981; }
    { const char * tb_v6982 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "TB_API void tb_gfx_cursor(int k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
