    { const char * tb_v7383 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7383; }
    { const char * tb_v7384 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v7384; }
    { const char * tb_v7385 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7385; }
    { const char * tb_v7386 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v7386; }
    { const char * tb_v7387 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7387; }
    { const char * tb_v7388 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7388; }
    { const char * tb_v7389 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7389; }
    { const char * tb_v7390 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v7390; }
    { const char * tb_v7391 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7391; }
    { const char * tb_v7392 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7392; }
    { const char * tb_v7393 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7393; }
    { const char * tb_v7394 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v7394; }
    { const char * tb_v7395 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v7395; }
    { const char * tb_v7396 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7396; }
    { const char * tb_v7397 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v7397; }
    { const char * tb_v7398 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v7398; }
    { const char * tb_v7399 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v7399; }
    { const char * tb_v7400 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v7400; }
    { const char * tb_v7401 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v7401; }
    { const char * tb_v7402 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v7402; }
    { const char * tb_v7403 = "// big — есть угол дальше 262 144 от центра сетки (в целые не влезает: только старый путь);\n"; *(const char * *)tb_grow(v_lines) = tb_v7403; }
    { const char * tb_v7404 = "// cull — какие грани не видны (0 — сетка не закрытая, считать все), cullok — cull уже посчитан;\n"; *(const char * *)tb_grow(v_lines) = tb_v7404; }
    { const char * tb_v7405 = "// gv, gt — где углы и треугольники сетки в памяти видеокарты; gused — в какой пачке видеокарта её рисует\n"; *(const char * *)tb_grow(v_lines) = tb_v7405; }
    { const char * tb_v7406 = "typedef struct { double *v; long long nv, capv; uint32_t *t, *c; long long n, cap; long long *hk; long long hcap;\n"; *(const char * *)tb_grow(v_lines) = tb_v7406; }
    { const char * tb_v7407 = "    int32_t *vi; double bb[6]; int big, cull, cullok; long long gv, gt, gused;\n"; *(const char * *)tb_grow(v_lines) = tb_v7407; }
    { const char * tb_v7408 = "    long long nch, *chr; double *chs, bs[4]; int chok; } tb_mesh;   // куски: chr — (первый треугольник, сколько), chs и bs — шары (центр, радиус)\n"; *(const char * *)tb_grow(v_lines) = tb_v7408; }
    { const char * tb_v7409 = "TB_API tb_mesh *tb_meshes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7409; }
    { const char * tb_v7410 = "TB_API long long tb_nmesh = 0, tb_capmesh = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7410; }
    { const char * tb_v7411 = "TB_API double tb_cam[9] = { 0, 0, -5,  1, 0, 0,  0, 1, 0 };   // где камера, вправо, вверх\n"; *(const char * *)tb_grow(v_lines) = tb_v7411; }
    { const char * tb_v7412 = "TB_API double tb_camf[3] = { 0, 0, 1 };                      // вперёд\n"; *(const char * *)tb_grow(v_lines) = tb_v7412; }
    { const char * tb_v7413 = "TB_API long long tb_mesh_new(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7413; }
    { const char * tb_v7414 = "    if (tb_nmesh == tb_capmesh) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7414; }
    { const char * tb_v7415 = "        tb_capmesh = tb_capmesh ? tb_capmesh * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7415; }
    { const char * tb_v7416 = "        tb_meshes = (tb_mesh *)realloc(tb_meshes, sizeof(tb_mesh) * tb_capmesh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7416; }
    { const char * tb_v7417 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7417; }
    { const char * tb_v7418 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v7418; }
    { const char * tb_v7419 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7419; }
    { const char * tb_v7420 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7420; }
    { const char * tb_v7421 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7421; }
    { const char * tb_v7422 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7422; }
    { const char * tb_v7423 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7423; }
    { const char * tb_v7424 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7424; }
    { const char * tb_v7425 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7425; }
    { const char * tb_v7426 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
    { const char * tb_v7428 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v7428; }
    { const char * tb_v7429 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7429; }
    { const char * tb_v7430 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v7430; }
    { const char * tb_v7431 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7431; }
    { const char * tb_v7432 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v7432; }
    { const char * tb_v7433 = "        long long *nk = (long long *)malloc(sizeof(long long) * nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v7433; }
    { const char * tb_v7434 = "        for (long long i = 0; i < nc; i++) nk[i] = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7434; }
    { const char * tb_v7435 = "        for (long long v = 0; v < m->nv; v++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7435; }
    { const char * tb_v7436 = "            uint64_t h = tb_vhash(m->v + 3 * v) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7436; }
    { const char * tb_v7437 = "            while (nk[h] >= 0) h = (h + 1) & (uint64_t)(nc - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7437; }
    { const char * tb_v7438 = "            nk[h] = v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7438; }
    { const char * tb_v7439 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7439; }
    { const char * tb_v7440 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v7440; }
    { const char * tb_v7441 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7441; }
    { const char * tb_v7442 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7442; }
    { const char * tb_v7443 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
    { const char * tb_v7444 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v7444; }
    { const char * tb_v7445 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7445; }
    { const char * tb_v7446 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7446; }
    { const char * tb_v7447 = "    if (m->nv == m->capv) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7447; }
    { const char * tb_v7448 = "        m->capv = m->capv ? m->capv * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7448; }
    { const char * tb_v7449 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7449; }
    { const char * tb_v7450 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v7450; }
    { const char * tb_v7451 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7451; }
    { const char * tb_v7452 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7452; }
    { const char * tb_v7453 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7453; }
    { const char * tb_v7454 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7454; }
    { const char * tb_v7455 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7455; }
    { const char * tb_v7456 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v7456; }
    { const char * tb_v7457 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v7457; }
    { const char * tb_v7458 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7458; }
    { const char * tb_v7459 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7459; }
    { const char * tb_v7460 = "    m->hk[h] = m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v7460; }
    { const char * tb_v7461 = "    return (uint32_t)m->nv++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7461; }
    { const char * tb_v7462 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7462; }
    { const char * tb_v7463 = "TB_API void tb_mesh_add(long long id, double x1, double y1, double z1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v7463; }
    { const char * tb_v7464 = "                        double x3, double y3, double z3, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7464; }
    { const char * tb_v7465 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7465; }
    { const char * tb_v7466 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v7466; }
    { const char * tb_v7467 = "    // видеокарта ещё не нарисовала эту сетку из текущей пачки: сначала отдать пачку (там старая сетка)\n"; *(const char * *)tb_grow(v_lines) = tb_v7467; }
    { const char * tb_v7468 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7468; }
    { const char * tb_v7469 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7469; }
    { const char * tb_v7470 = "    m->cullok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7470; }
    { const char * tb_v7471 = "    m->chok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7471; }
    { const char * tb_v7472 = "    if (m->n == m->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7472; }
    { const char * tb_v7473 = "        m->cap = m->cap ? m->cap * 2 : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v7473; }
    { const char * tb_v7474 = "        m->t = (uint32_t *)realloc(m->t, sizeof(uint32_t) * 3 * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7474; }
    { const char * tb_v7475 = "        m->c = (uint32_t *)realloc(m->c, sizeof(uint32_t) * m->cap);\n"; *(const char * *)tb_grow(v_lines) = tb_v7475; }
    { const char * tb_v7476 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7476; }
    { const char * tb_v7477 = "    uint32_t *t = m->t + 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7477; }
    { const char * tb_v7478 = "    t[0] = tb_mesh_vertex(m, x1, y1, z1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7478; }
    { const char * tb_v7479 = "    t[1] = tb_mesh_vertex(m, x2, y2, z2);\n"; *(const char * *)tb_grow(v_lines) = tb_v7479; }
    { const char * tb_v7480 = "    t[2] = tb_mesh_vertex(m, x3, y3, z3);\n"; *(const char * *)tb_grow(v_lines) = tb_v7480; }
    { const char * tb_v7481 = "    m->c[m->n++] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7481; }
    { const char * tb_v7482 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7482; }
    { const char * tb_v7483 = "TB_API void tb_camera(double x, double y, double z, double lx, double ly, double lz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7483; }
    { const char * tb_v7484 = "    double f[3] = { lx - x, ly - y, lz - z }, l = sqrt(f[0] * f[0] + f[1] * f[1] + f[2] * f[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7484; }
    { const char * tb_v7485 = "    if (l < 1e-12) return;   // смотреть в себя нельзя: камера не меняется\n"; *(const char * *)tb_grow(v_lines) = tb_v7485; }
    { const char * tb_v7486 = "    for (int i = 0; i < 3; i++) f[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7486; }
    { const char * tb_v7487 = "    double up[3] = { 0, 1, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7487; }
    { const char * tb_v7488 = "    if (fabs(f[1]) > 0.9999) { up[1] = 0; up[2] = 1; }   // смотрим прямо вверх или вниз\n"; *(const char * *)tb_grow(v_lines) = tb_v7488; }
    { const char * tb_v7489 = "    double r[3] = { up[1] * f[2] - up[2] * f[1], up[2] * f[0] - up[0] * f[2], up[0] * f[1] - up[1] * f[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7489; }
    { const char * tb_v7490 = "    l = sqrt(r[0] * r[0] + r[1] * r[1] + r[2] * r[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7490; }
    { const char * tb_v7491 = "    for (int i = 0; i < 3; i++) r[i] /= l;\n"; *(const char * *)tb_grow(v_lines) = tb_v7491; }
    { const char * tb_v7492 = "    double u[3] = { f[1] * r[2] - f[2] * r[1], f[2] * r[0] - f[0] * r[2], f[0] * r[1] - f[1] * r[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v7492; }
    { const char * tb_v7493 = "    tb_cam[0] = x; tb_cam[1] = y; tb_cam[2] = z;\n"; *(const char * *)tb_grow(v_lines) = tb_v7493; }
    { const char * tb_v7494 = "    for (int i = 0; i < 3; i++) { tb_cam[3 + i] = r[i]; tb_cam[6 + i] = u[i]; tb_camf[i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7494; }
    { const char * tb_v7495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7495; }
    { const char * tb_v7496 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v7496; }
    { const char * tb_v7497 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7497; }
    { const char * tb_v7498 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7498; }
    { const char * tb_v7499 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v7499; }
    { const char * tb_v7500 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v7500; }
    { const char * tb_v7501 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v7501; }
    { const char * tb_v7502 = "    double ax = ((dd[1] - dd[0]) * e2y - (dd[2] - dd[0]) * e1y) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7502; }
    { const char * tb_v7503 = "    double by = ((dd[2] - dd[0]) * e1x - (dd[1] - dd[0]) * e2x) * ia;\n"; *(const char * *)tb_grow(v_lines) = tb_v7503; }
    { const char * tb_v7504 = "    if (ax > 1e9) ax = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7504; }
    { const char * tb_v7505 = "    if (ax < -1e9) ax = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7505; }
    { const char * tb_v7506 = "    if (by > 1e9) by = 1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7506; }
    { const char * tb_v7507 = "    if (by < -1e9) by = -1e9;\n"; *(const char * *)tb_grow(v_lines) = tb_v7507; }
    { const char * tb_v7508 = "    double c0 = dd[0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v7508; }
    { const char * tb_v7509 = "    // в целые: точка берётся по центру (2x + 1) / 2, поэтому ax / 2; ещё × 64 для точности\n"; *(const char * *)tb_grow(v_lines) = tb_v7509; }
    { const char * tb_v7510 = "    pl[0] = (uint32_t)tb_rnd(ax * 32); pl[1] = (uint32_t)tb_rnd(by * 32); pl[2] = (uint32_t)tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v7510; }
    { const char * tb_v7511 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7511; }
    { const char * tb_v7512 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7512; }
    { const char * tb_v7513 = "// углы сетки после камеры: место перед камерой и на экране (округлённое), глубина D\n"; *(const char * *)tb_grow(v_lines) = tb_v7513; }
    { const char * tb_v7514 = "typedef struct { double cx, cy, cz, sx, sy, dd; long long rx, ry; int front, near_ok; } tb_3v;\n"; *(const char * *)tb_grow(v_lines) = tb_v7514; }
