    { const char * tb_v7549 = "            v->dd = (1 - zn * iz) * 16777216.0;   // D = (1 - zn / z) * 2^24 — по экрану меняется ровно по плоскости\n"; *(const char * *)tb_grow(v_lines) = tb_v7549; }
    { const char * tb_v7550 = "            v->near_ok = v->sx >= gx0 && v->sx <= gx1 && v->sy >= gy0 && v->sy <= gy1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7550; }
    { const char * tb_v7551 = "            if (v->near_ok) { v->rx = tb_rnd(v->sx); v->ry = tb_rnd(v->sy); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7551; }
    { const char * tb_v7552 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7552; }
