    { const char * tb_v7560 = "            double sx[3] = { v0->sx, v1->sx, v2->sx }, sy[3] = { v0->sy, v1->sy, v2->sy }, dd[3] = { v0->dd, v1->dd, v2->dd };\n"; *(const char * *)tb_grow(v_lines) = tb_v7560; }
    { const char * tb_v7561 = "            if (!tb_tri3_plane(sx, sy, dd, pl)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7561; }
    { const char * tb_v7562 = "            if (v0->near_ok && v1->near_ok && v2->near_ok) {   // обычный случай: целиком в рамке\n"; *(const char * *)tb_grow(v_lines) = tb_v7562; }
    { const char * tb_v7563 = "                long long q[6] = { v0->rx, v0->ry, v1->rx, v1->ry, v2->rx, v2->ry };\n"; *(const char * *)tb_grow(v_lines) = tb_v7563; }
    { const char * tb_v7564 = "                tb_tri_draw_i(q, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7564; }
    { const char * tb_v7565 = "            } else tb_poly_draw(sx, sy, 3, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7565; }
    { const char * tb_v7566 = "            continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7566; }
    { const char * tb_v7567 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7567; }
    { const char * tb_v7568 = "        // часть треугольника за камерой: обрезаем всё ближе zn — выходит 0, 3 или 4 угла\n"; *(const char * *)tb_grow(v_lines) = tb_v7568; }
    { const char * tb_v7569 = "        tb_3v *vs[3] = { v0, v1, v2 };\n"; *(const char * *)tb_grow(v_lines) = tb_v7569; }
