    { const char * tb_v7573 = "            const tb_3v *p = vs[i], *q = vs[(i + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7573; }
    { const char * tb_v7574 = "            if (p->front) { qx[n] = p->cx; qy[n] = p->cy; qz[n] = p->cz; n++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7574; }
    { const char * tb_v7575 = "            if (p->front != q->front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7575; }
    { const char * tb_v7576 = "                double k = (zn - p->cz) / (q->cz - p->cz);\n"; *(const char * *)tb_grow(v_lines) = tb_v7576; }
    { const char * tb_v7577 = "                qx[n] = p->cx + (q->cx - p->cx) * k; qy[n] = p->cy + (q->cy - p->cy) * k; qz[n] = zn; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7577; }
    { const char * tb_v7578 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7578; }
    { const char * tb_v7579 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7579; }
    { const char * tb_v7580 = "        if (n < 3) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7580; }
    { const char * tb_v7581 = "        double sx[4], sy[4], dd[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v7581; }
    { const char * tb_v7582 = "        for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7582; }
    { const char * tb_v7583 = "            double iz = 1 / qz[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7583; }
    { const char * tb_v7584 = "            sx[i] = hw + f * qx[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7584; }
    { const char * tb_v7585 = "            sy[i] = hh - f * qy[i] * iz;\n"; *(const char * *)tb_grow(v_lines) = tb_v7585; }
    { const char * tb_v7586 = "            dd[i] = (1 - zn * iz) * 16777216.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7586; }
    { const char * tb_v7587 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7587; }
    { const char * tb_v7588 = "        if (!tb_tri3_plane(sx, sy, dd, pl)) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7588; }
    { const char * tb_v7589 = "        tb_poly_draw(sx, sy, n, m->c[t], pl);\n"; *(const char * *)tb_grow(v_lines) = tb_v7589; }
    { const char * tb_v7590 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7590; }
    { const char * tb_v7591 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7591; }
    { const char * tb_v7592 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v7592; }
    { const char * tb_v7593 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v7593; }
    { const char * tb_v7594 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7594; }
    { const char * tb_v7595 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v7595; }
    { const char * tb_v7596 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v7596; }
    { const char * tb_v7597 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7597; }
    { const char * tb_v7598 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v7598; }
    { const char * tb_v7599 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7599; }
    { const char * tb_v7600 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v7600; }
    { const char * tb_v7601 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7601; }
    { const char * tb_v7602 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7602; }
    { const char * tb_v7603 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7603; }
    { const char * tb_v7604 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7604; }
    { const char * tb_v7605 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7605; }
    { const char * tb_v7606 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v7606; }
    { const char * tb_v7607 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7607; }
    { const char * tb_v7608 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7608; }
    { const char * tb_v7609 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v7609; }
    { const char * tb_v7610 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v7610; }
    { const char * tb_v7611 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7611; }
    { const char * tb_v7612 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7612; }
    { const char * tb_v7613 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7613; }
    { const char * tb_v7614 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7614; }
    { const char * tb_v7615 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7615; }
    { const char * tb_v7616 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v7616; }
    { const char * tb_v7617 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7617; }
    { const char * tb_v7618 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v7618; }
    { const char * tb_v7619 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7619; }
    { const char * tb_v7620 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7620; }
    { const char * tb_v7621 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7621; }
    { const char * tb_v7622 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v7622; }
    { const char * tb_v7623 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v7623; }
    { const char * tb_v7624 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v7624; }
    { const char * tb_v7625 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7625; }
    { const char * tb_v7626 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v7626; }
    { const char * tb_v7627 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v7627; }
    { const char * tb_v7628 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7628; }
    { const char * tb_v7629 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7629; }
    { const char * tb_v7630 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v7630; }
    { const char * tb_v7631 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7631; }
    { const char * tb_v7632 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7632; }
    { const char * tb_v7633 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v7633; }
    { const char * tb_v7634 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7634; }
    { const char * tb_v7635 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7635; }
    { const char * tb_v7636 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7636; }
