    { const char * tb_v7678 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v7678; }
    { const char * tb_v7679 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v7679; }
    { const char * tb_v7680 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7680; }
    { const char * tb_v7681 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v7681; }
