    { const char * tb_v8325 = "// тон: синус hz герц на ms миллисекунд, мягкое начало и конец (без щелчков)\n"; *(const char * *)tb_grow(v_lines) = tb_v8325; }
    { const char * tb_v8326 = "TB_API long long tb_play_tone(double hz, long long ms) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8326; }
    { const char * tb_v8327 = "    if (ms <= 0 || hz <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8327; }
    { const char * tb_v8328 = "    if (ms > 60000) ms = 60000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8328; }
    { const char * tb_v8329 = "    long long n = ms * TB_SR / 1000;\n"; *(const char * *)tb_grow(v_lines) = tb_v8329; }
    { const char * tb_v8330 = "    float *d = malloc(sizeof(float) * (size_t)(n + 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v8330; }
    { const char * tb_v8331 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8331; }
    { const char * tb_v8332 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v8332; }
    { const char * tb_v8333 = "    if (ramp * 2 > n) ramp = n / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8333; }
    { const char * tb_v8334 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8334; }
    { const char * tb_v8335 = "        double e = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8335; }
    { const char * tb_v8336 = "        if (i < ramp) e = (double)i / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8336; }
    { const char * tb_v8337 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v8337; }
    { const char * tb_v8338 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v8338; }
    { const char * tb_v8339 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8339; }
    { const char * tb_v8340 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v8340; }
    { const char * tb_v8341 = "    if (s < 0) { free(d); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8341; }
    { const char * tb_v8342 = "    long long v = tb_voice_new(s, 0, 0, 0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8342; }
    { const char * tb_v8343 = "    if (v == 0) { pthread_mutex_lock(&tb_slock); free(tb_snds[s].d); tb_snds[s].d = 0; pthread_mutex_unlock(&tb_slock); }\n"; *(const char * *)tb_grow(v_lines) = tb_v8343; }
    { const char * tb_v8344 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v8344; }
    { const char * tb_v8345 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8345; }
