    { const char * tb_v8398 = "    for (int i = 0; i < 3; i++) { tb_lis[3 + i] = r[i] / l; tb_lis[6 + i] = f[i]; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8398; }
